from pydantic import BaseModel, Field, validator


class ETF(BaseModel):
    """ETF数据模型"""
    code: str = Field(..., description="ETF代码")
    name: str = Field(..., description="ETF名称")
    management_company: str = Field(..., description="基金管理公司")
    current_price: float = Field(..., description="当前价格")
    change_pct: float = Field(..., description="涨跌幅")
    volume: float = Field(..., description="成交量")
    amount: float = Field(..., description="成交额")
    setup_date: str = Field(..., description="成立日期")
    list_date: str = Field(..., description="上市日期")
    fund_type: str = Field(default="ETF", description="基金类型")
    status: str = Field(default="L", description="状态")
    trade_date: str = Field(..., description="交易日期")
    data_age_days: int = Field(..., description="数据时效性（天数）")

    @validator("code")
    def validate_code(cls, v):
        if not v.isalnum():
            raise ValueError("ETF代码必须是字母和数字的组合")
        return v

    @validator("name")
    def validate_name(cls, v):
        if not v.strip():
            raise ValueError("ETF名称不能为空")
        return v

    @validator("management_company")
    def validate_management_company(cls, v):
        if not v.strip():
            raise ValueError("基金管理公司不能为空")
        return v

    @validator("current_price")
    def validate_current_price(cls, v):
        if v < 0:
            raise ValueError("当前价格不能为负数")
        return v

    @validator("change_pct")
    def validate_change_pct(cls, v):
        if v < -100 or v > 100:
            raise ValueError("涨跌幅不能超过100%")
        return v

    @validator("volume")
    def validate_volume(cls, v):
        if v < 0:
            raise ValueError("成交量不能为负数")
        return v

    @validator("amount")
    def validate_amount(cls, v):
        if v < 0:
            raise ValueError("成交额不能为负数")
        return v

