        except ValueError:
            raise ValueError("成立日期格式

gql`
  query GetAnyEquipmentByID($id: ID!) {
    anyEquipment(id: $id) {
      id
      name
      archived
    }
  }
`;

export const GET_EQUIPMENT_BY_NAME = gql`
  query GetEquipmentByName($name: String!) {
    equipment(name: $name) {
      id
      name
      archived
      imageUrl
      sopUrl
      room {
        id
        name
        makerspace {
          id
          name
        }
      }
      trainingModules {
        id
        name
      }
      notes
      numAvailable
      numInUse
      byReservationOnly
      needsWelcome
    }
  }
`;

